window.WHITAKER_STORIES = [{"slug": "cecilia-de-vicariis", "name": "Cecilia De Vicariis", "institution": "University of Genoa", "mapInstitution": "University of Genoa", "kind": "Interview", "title": "Learning by building, across two continents", "intro": "Cecilia De Vicariis’s biomedical engineering training at Genoa led to a six-month thesis experience at Marquette University in Milwaukee. Working abroad brought a new balance between classroom theory and the practical demands of a research project.", "thumbnail": "assets/cecilia-de-vicariis-1.jpg", "date": "8 April 2019", "searchText": "Cecilia De Vicariis University of Genoa Biomedical engineering master’s graduate Learning by building, across two continents Cecilia De Vicariis’s biomedical engineering training at Genoa led to a six-month thesis experience at Marquette University in Milwaukee. Working abroad brought a new balance between classroom theory and the practical demands of a research project. Interview Her project involved a neuroprosthetic device developed to test finger dexterity in people who had experienced a stroke. The work challenged her to develop electronics and software skills, connecting engineering concepts to a rehabilitation problem. The exchange also meant learning to collaborate across a time difference and adapting to a different university culture. Campus life and the experience of building something tangible became memorable parts of her education. At the time of the interview, she was considering doctoral study as her next step."}, {"slug": "maura-casadio", "name": "Maura Casadio", "institution": "University of Genoa", "mapInstitution": "University of Genoa", "kind": "Interview", "title": "Finding a shared language for rehabilitation", "intro": "Maura Casadio’s route into rehabilitation research connected electronic engineering, robotics, and an international postdoctoral experience. At Genoa, her work brought engineers into conversation with the people who understand rehabilitation from the clinical side.", "thumbnail": "assets/maura-casadio-1.jpg", "date": "8 April 2019", "searchText": "Maura Casadio University of Genoa Associate professor of biomedical engineering Finding a shared language for rehabilitation Maura Casadio’s route into rehabilitation research connected electronic engineering, robotics, and an international postdoctoral experience. At Genoa, her work brought engineers into conversation with the people who understand rehabilitation from the clinical side. Interview After studying in Pisa and completing a doctorate in Genoa, she worked at the Rehabilitation Institute of Chicago and Northwestern University. Her research interests included neural control, rehabilitation robotics, and body–machine interfaces: technologies that require both engineering insight and an understanding of human movement. Casadio emphasized the importance of a common language among engineers, therapists, and psychologists. She also valued research environments where students could ask difficult questions. Supportive mentorship and open discussion helped shape the collaborative approach she brought back to her own teaching and research."}, {"slug": "giulia-ballardini", "name": "Giulia Ballardini", "institution": "University of Genoa", "mapInstitution": "University of Genoa", "kind": "Interview", "title": "From biomaterials to sensory feedback", "intro": "Giulia Ballardini’s studies took her from biomedical engineering in Bologna to neuroengineering in Genoa. An experience at Marquette University helped her see how those interests could become hands-on rehabilitation research.", "thumbnail": "assets/giulia-ballardini-1.jpg", "date": "8 April 2019", "searchText": "Giulia Ballardini University of Genoa PhD student in biomedical engineering From biomaterials to sensory feedback Giulia Ballardini’s studies took her from biomedical engineering in Bologna to neuroengineering in Genoa. An experience at Marquette University helped her see how those interests could become hands-on rehabilitation research. Interview Working with vibrotactile feedback for people recovering from stroke connected her engineering training with rehabilitation research. By the time of her interview, she had chosen sensory substitution as a field for her doctorate and was working to define a specific project within it. Her interview paired enthusiasm for meaningful research with an appreciation of campus community. Rather than describing a career planned from the beginning, she described learning through each stage and taking the next decision one step at a time."}, {"slug": "giorgia-marchesi", "name": "Giorgia Marchesi", "institution": "University of Genoa", "mapInstitution": "University of Genoa", "kind": "Interview", "title": "Choosing a path by experiencing other places", "intro": "For Giorgia Marchesi, international study was a way to explore both research and the kind of life she wanted to build. Her neuroengineering education included experiences in the Netherlands and the United States.", "thumbnail": "assets/giorgia-marchesi-1.jpg", "date": "8 April 2019", "searchText": "Giorgia Marchesi University of Genoa PhD student in neural engineering and robotics Choosing a path by experiencing other places For Giorgia Marchesi, international study was a way to explore both research and the kind of life she wanted to build. Her neuroengineering education included experiences in the Netherlands and the United States. Interview During her master’s training, she spent time at Radboud University through Erasmus and pursued thesis research at the City College of New York School of Medicine. These experiences exposed her to different educational cultures and approaches to scientific work. Marchesi was drawn to projects with a meaningful connection to people’s lives. Working in different places helped her test her interests through experience, rather than choosing a future entirely in the abstract. Her story highlights curiosity as a practical tool for making career decisions."}, {"slug": "federico-barban", "name": "Federico Barban", "institution": "University of Genoa", "mapInstitution": "University of Genoa", "kind": "Interview", "title": "Engineering a connection to the nervous system", "intro": "Federico Barban chose engineering as his way into questions about the body and the brain. His biomedical engineering studies at Genoa developed into doctoral work in neuroprosthetics.", "thumbnail": "assets/federico-barban-1.jpg", "date": "8 April 2019", "searchText": "Federico Barban University of Genoa PhD student in neuroengineering Engineering a connection to the nervous system Federico Barban chose engineering as his way into questions about the body and the brain. His biomedical engineering studies at Genoa developed into doctoral work in neuroprosthetics. Interview In the interview, he described research involving electrical brain stimulation in a rat model of stroke. The work linked engineering methods with experimental neuroscience, exploring questions relevant to recovery rather than presenting a finished clinical treatment. Hands-on teaching helped spark his interest in science, while experience abroad broadened his perspective beyond the laboratory. He valued work that felt meaningful and a career in which engineering could contribute to understanding—and eventually helping—people."}, {"slug": "gastone-ciuti", "name": "Gastone Ciuti", "institution": "Scuola Superiore Sant'Anna - BioRobotics Institute", "mapInstitution": "Scuola Superiore Sant'Anna - BioRobotics Institute", "kind": "Interview", "title": "Robotics with a clinical purpose", "intro": "At the BioRobotics Institute in Pisa, Gastone Ciuti led the Computer-Integrated Technologies for Robotic Surgery Laboratory. His research connected robotic engineering with minimally invasive diagnosis and surgery.", "thumbnail": "assets/gastone-ciuti-1.jpg", "date": "5 April 2019", "searchText": "Gastone Ciuti Scuola Superiore Sant'Anna - BioRobotics Institute Assistant professor of biomedical robotics Robotics with a clinical purpose At the BioRobotics Institute in Pisa, Gastone Ciuti led the Computer-Integrated Technologies for Robotic Surgery Laboratory. His research connected robotic engineering with minimally invasive diagnosis and surgery. Interview His path included engineering degrees at the University of Pisa and a doctorate at Scuola Superiore Sant’Anna. The laboratory worked on technologies for gastrointestinal and cardiovascular applications. It also welcomed international researchers, including Whitaker fellow Levin Sliker in 2013. Ciuti’s interview connected sustained effort with the possibility of useful clinical impact. Pisa’s research community was part of that story: a setting where technical expertise and collaboration could support ideas that move between engineering and medicine."}, {"slug": "jaclyn-brennan", "name": "Jaclyn Brennan", "institution": "Ecole Polytechnique", "mapInstitution": "Ecole Polytechnique", "kind": "Interview", "title": "A year to ask new questions", "intro": "After a master’s experience in tissue engineering, Jaclyn Brennan still had research questions she wanted to explore. A Whitaker fellowship at École Polytechnique offered time to pursue them while living in France.", "thumbnail": "assets/jaclyn-brennan-1.jpg", "date": "4 February 2019", "searchText": "Jaclyn Brennan Ecole Polytechnique Whitaker fellow, 2012 A year to ask new questions After a master’s experience in tissue engineering, Jaclyn Brennan still had research questions she wanted to explore. A Whitaker fellowship at École Polytechnique offered time to pursue them while living in France. Interview The fellowship gave her an opportunity to develop greater independence in research without immediately committing to a doctoral program. Working in a laboratory with mathematicians, physicists, and biologists also showed her how an engineering perspective could contribute to a broader team. Her decision combined scientific curiosity with a wish to experience another culture. In the interview, the value of the year lay in both: space to test a research direction and the daily experience of learning with people whose training differed from her own."}, {"slug": "hannah-meredith", "name": "Hannah Meredith", "institution": "London School of Hygiene & Tropical Medicine (LSHTM)", "mapInstitution": "London School of Hygiene & Tropical Medicine (LSHTM)", "kind": "Interview", "title": "Bringing engineering questions into global health", "intro": "Hannah Meredith’s path from biomedical engineering to public health grew through fieldwork and international collaboration. After a Duke doctorate, she pursued a Whitaker experience at the London School of Hygiene & Tropical Medicine.", "thumbnail": "assets/hannah-meredith-1.jpg", "date": "3 June 2019", "searchText": "Hannah Meredith London School of Hygiene & Tropical Medicine (LSHTM) Whitaker International Scholar, 2017; later postdoctoral researcher Bringing engineering questions into global health Hannah Meredith’s path from biomedical engineering to public health grew through fieldwork and international collaboration. After a Duke doctorate, she pursued a Whitaker experience at the London School of Hygiene & Tropical Medicine. Interview An earlier field experience in Sri Lanka helped connect her quantitative training with public health questions. By the time of her interview, she was a postdoctoral researcher at Johns Hopkins studying human mobility and malaria. Meredith chose her London host with attention to collaborators, resources, and opportunities for fieldwork. Her story shows how engineering training can travel beyond a traditional engineering department, providing tools for questions that depend on understanding people and places as well as data."}, {"slug": "patrick-boyle", "name": "Patrick Boyle", "institution": "University of Washington", "mapInstitution": "", "kind": "Interview", "title": "A computational career shaped by going abroad", "intro": "Patrick Boyle’s work at the University of Washington used computer models to investigate heart rhythm disorders. His route into that field included engineering training in Calgary, an internship in Japan, and research at Johns Hopkins.", "thumbnail": "assets/patrick-boyle-1.jpg", "date": "8 January 2020", "searchText": "Patrick Boyle University of Washington Assistant professor of bioengineering A computational career shaped by going abroad Patrick Boyle’s work at the University of Washington used computer models to investigate heart rhythm disorders. His route into that field included engineering training in Calgary, an internship in Japan, and research at Johns Hopkins. Interview An eleven-month internship at Sanyo in 2002–2003 was a formative international experience. Later, working with Natalia Trayanova, he investigated cardiac optogenetics and personalized models relevant to ablation research. These experiences helped shape his direction in computational cardiac science. Boyle’s interview connected scientific curiosity with the willingness to enter an unfamiliar environment. An experience abroad could change more than technical skills: it could widen a person’s sense of possible careers and of how to work with others."}, {"slug": "pierre-sacre", "name": "Pierre Sacré", "institution": "University of Liège", "mapInstitution": "", "kind": "Interview", "title": "Fundamental questions, future possibilities", "intro": "Pierre Sacré worked at the interface of neural systems and artificial devices. His academic path included a Fulbright experience from Belgium to the United States in 2014 and postdoctoral research at Johns Hopkins.", "thumbnail": "", "date": "24 November 2019", "searchText": "Pierre Sacré University of Liège Assistant professor, electrical engineering and computer science Fundamental questions, future possibilities Pierre Sacré worked at the interface of neural systems and artificial devices. His academic path included a Fulbright experience from Belgium to the United States in 2014 and postdoctoral research at Johns Hopkins. Interview His research combined nonlinear dynamical systems, statistical methods, and data science to connect observed neural activity and behavior with the mechanisms that produce them. It was work grounded in fundamental questions, rather than an immediately available treatment. Sacré described potential future benefits for patients as a motivation for doing that foundational work. His perspective connected mathematical and engineering methods with a long view of impact: discoveries may become useful through the work of other researchers as well as one’s own."}, {"slug": "shelly-chang", "name": "Shelly Chang", "institution": "Academia Sinica - Institute of Biomedical Sciences", "mapInstitution": "Academia Sinica - Institute of Biomedical Sciences", "kind": "Interview", "title": "Learning the habits of a researcher", "intro": "Shelly Chang’s interest in biology grew through teachers and mentors who made experimental science engaging. At Academia Sinica, her doctoral research involved antibodies and their relevance to therapeutic development.", "thumbnail": "assets/shelly-chang-1.jpg", "date": "January 2019", "searchText": "Shelly Chang Academia Sinica - Institute of Biomedical Sciences PhD student Learning the habits of a researcher Shelly Chang’s interest in biology grew through teachers and mentors who made experimental science engaging. At Academia Sinica, her doctoral research involved antibodies and their relevance to therapeutic development. Interview She worked with Whitaker fellow Teagan Adamson in 2013 at the Institute of Biomedical Sciences. In her interview, she described learning not only experimental techniques but also how to organize a research question and plan the steps needed to investigate it. Mentorship remained central to her story. Her advisor helped her develop a more logical approach to research and greater confidence using English in a scientific setting. These everyday forms of guidance were part of becoming an independent scientist."}, {"slug": "elyse-watkins", "name": "Elyse Watkins", "institution": "ETH Zurich", "mapInstitution": "ETH Zurich", "kind": "Interview", "title": "A summer that opened up a scientific community", "intro": "Elyse Watkins’s international research experience began with a ThinkSwiss-supported summer in Sai Reddy’s laboratory at ETH Zurich in Basel. It became an important example of a welcoming, interdisciplinary scientific community.", "thumbnail": "assets/elyse-watkins-1.jpg", "date": "18 October 2019", "searchText": "Elyse Watkins ETH Zurich Molecular engineering PhD student, University of Chicago A summer that opened up a scientific community Elyse Watkins’s international research experience began with a ThinkSwiss-supported summer in Sai Reddy’s laboratory at ETH Zurich in Basel. It became an important example of a welcoming, interdisciplinary scientific community. Interview By the time of the interview, she was a molecular engineering doctoral student at the University of Chicago, researching protein therapeutics in a systems and synthetic immunology laboratory. Her earlier training included biomedical engineering at Georgia Tech. She valued collaboration across disciplines and a laboratory culture in which people supported one another and shared credit. This is an international biomedical engineering story from the broader EverydayBME archive; her Swiss exchange was supported by ThinkSwiss, rather than Whitaker."}, {"slug": "yueqi-guo", "name": "Yueqi Guo", "institution": "Johns Hopkins University", "mapInstitution": "", "kind": "Interview", "title": "Seeing neural activity through an engineering lens", "intro": "Yueqi Guo’s interest in both medicine and engineering led from undergraduate study at Tsinghua University to graduate study at Johns Hopkins. Her research connected optical imaging with questions about the brain.", "thumbnail": "assets/yueqi-guo-1.jpg", "date": "1 December 2019", "searchText": "Yueqi Guo Johns Hopkins University PhD student Seeing neural activity through an engineering lens Yueqi Guo’s interest in both medicine and engineering led from undergraduate study at Tsinghua University to graduate study at Johns Hopkins. Her research connected optical imaging with questions about the brain. Interview She described studying neural processing of sound in marmosets. The project brought together imaging methods and neuroscience, using engineering tools to investigate how a biological system handles information. Her account also emphasized the community around the research. Help from others made adapting to a new environment easier, and lively laboratory discussions made scientific work intellectually engaging. The experience of learning abroad was social as well as technical."}, {"slug": "yadi-chen", "name": "Yadi Chen", "institution": "University of Auckland", "mapInstitution": "University of Auckland", "kind": "Interview", "title": "From engineering training to the biology of vision", "intro": "Yadi Chen’s studies took her from China to New Zealand and from biomedical engineering into physiology. At Auckland, she investigated the eye’s lens and questions connected to age-related eye disease.", "thumbnail": "assets/yadi-chen-1.jpg", "date": "29 October 2019", "searchText": "Yadi Chen University of Auckland PhD student in physiology From engineering training to the biology of vision Yadi Chen’s studies took her from China to New Zealand and from biomedical engineering into physiology. At Auckland, she investigated the eye’s lens and questions connected to age-related eye disease. Interview A major part of the doctoral journey involved building an experimental system before applying it to biological questions. That process joined practical engineering skills with cellular physiology and optics. Her story illustrates the less visible work behind a research result: developing the tools, learning how a system behaves, and only then using it to investigate disease. Moving between disciplines gave her different ways to approach the same problem."}, {"slug": "steph-khuu", "name": "Steph Khuu", "institution": "Auckland Bioengineering Institute, University of Auckland", "mapInstitution": "Auckland Bioengineering Institute, University of Auckland", "kind": "Interview", "title": "Connecting muscle experiments and computer models", "intro": "Steph Khuu’s research at the Auckland Bioengineering Institute investigated muscle regeneration in the context of cerebral palsy. Her project combined computational modeling with experimental work.", "thumbnail": "assets/steph-khuu-1.jpg", "date": "2019", "searchText": "Steph Khuu Auckland Bioengineering Institute, University of Auckland PhD student Connecting muscle experiments and computer models Steph Khuu’s research at the Auckland Bioengineering Institute investigated muscle regeneration in the context of cerebral palsy. Her project combined computational modeling with experimental work. Interview Her earlier physiology training included neurophysiology and laboratory work on brain cells. She also spent time on the BabyX digital-brain project before moving into muscle research. These experiences connected biological questions with tools from engineering and computation. The interview shows a career developing through connections between fields. Building models and testing them against experiments offered complementary ways to understand a complex biological system, with each approach helping to sharpen questions for the other."}, {"slug": "colin-hisey", "name": "Colin Hisey", "institution": "University of Auckland", "mapInstitution": "University of Auckland", "kind": "Interview", "title": "Building a research life across borders", "intro": "Colin Hisey trained in chemical engineering before building a research career around extracellular vesicles. A Whitaker experience in Spain’s Basque Country helped make international research a lasting part of his life.", "thumbnail": "assets/colin-hisey-1.jpg", "date": "2019", "searchText": "Colin Hisey University of Auckland Research fellow, Hub for Extracellular Vesicle Investigations Building a research life across borders Colin Hisey trained in chemical engineering before building a research career around extracellular vesicles. A Whitaker experience in Spain’s Basque Country helped make international research a lasting part of his life. Interview At Auckland, he supported researchers through training, experiment planning, and scientific meetings while developing his own projects. One focus was a microfluidic platform to capture selected extracellular vesicles from small biological samples for further analysis. His move to New Zealand followed a job application made while finishing his doctorate. In reflecting on international science, he emphasized relationships built through working together day after day. Those connections—and time spent exploring a new home beyond the laboratory—were central to his experience."}, {"slug": "martyn-nash", "name": "Martyn Nash", "institution": "Auckland Bioengineering Institute, University of Auckland", "mapInstitution": "Auckland Bioengineering Institute, University of Auckland", "kind": "Interview", "title": "Reading the mechanics of living tissue", "intro": "Martyn “Marty” Nash’s research connected medical images with the mechanics of soft tissues. At Auckland, personalized biomechanical models offered a way to ask questions that images alone could not answer.", "thumbnail": "assets/martyn-nash-1.jpg", "date": "2019", "searchText": "Martyn Nash Auckland Bioengineering Institute, University of Auckland Professor of biomedical engineering Reading the mechanics of living tissue Martyn “Marty” Nash’s research connected medical images with the mechanics of soft tissues. At Auckland, personalized biomechanical models offered a way to ask questions that images alone could not answer. Interview His work combined three-dimensional MRI or ultrasound information with mechanical loads to investigate properties such as heart-muscle elasticity and contractility. Related questions involved the way breast tissue deforms during imaging. Nash’s interview described movement between different kinds of science, including mechanics and electrophysiology. Keeping options open and learning new methods allowed his work to develop across disciplinary boundaries, linking mathematical models with biological measurements."}, {"slug": "megan-guidry", "name": "Megan Guidry", "institution": "Auckland Bioengineering Institute, University of Auckland", "mapInstitution": "Auckland Bioengineering Institute, University of Auckland", "kind": "Interview", "title": "From heart research to helping researchers learn", "intro": "Megan Guidry’s Whitaker award brought her to New Zealand in early 2015. Her initial research examined calcium and the mechanics of the heart’s left ventricle; her later role supported researchers across many fields.", "thumbnail": "assets/megan-guidry-1.jpg", "date": "2019", "searchText": "Megan Guidry Auckland Bioengineering Institute, University of Auckland Research training coordinator, New Zealand eScience Infrastructure From heart research to helping researchers learn Megan Guidry’s Whitaker award brought her to New Zealand in early 2015. Her initial research examined calcium and the mechanics of the heart’s left ventricle; her later role supported researchers across many fields. Interview At the time of the interview, she coordinated training for New Zealand eScience Infrastructure and worked with the Carpentries community. The focus included coding and data-management skills that help researchers do their work more effectively. Her story expands the picture of what a research career can become. Experience in a scientific project can also provide a foundation for teaching, building communities, and helping other researchers develop the practical skills they need."}, {"slug": "paul-donaldson", "name": "Paul Donaldson", "institution": "University of Auckland", "mapInstitution": "University of Auckland", "kind": "Interview", "title": "When optics meets cell biology", "intro": "Paul Donaldson’s research investigated the physiology of the eye’s lens, including questions related to cataract and presbyopia. International collaboration brought complementary perspectives into that work.", "thumbnail": "assets/paul-donaldson-1.jpg", "date": "2019", "searchText": "Paul Donaldson University of Auckland Lens physiology researcher When optics meets cell biology Paul Donaldson’s research investigated the physiology of the eye’s lens, including questions related to cataract and presbyopia. International collaboration brought complementary perspectives into that work. Interview In the interview, he recalled meeting a future Whitaker fellow at a conference in Kona. The resulting visit connected expertise in optics and mechanics with the laboratory’s lens-biology research. The collaboration illustrated how a conversation can grow into a sustained scientific relationship. Researchers with different skills could approach the same organ from different directions, helping one another identify questions and methods that would be harder to develop alone."}, {"slug": "thor-besier", "name": "Thor Besier", "institution": "Auckland Bioengineering Institute, University of Auckland", "mapInstitution": "Auckland Bioengineering Institute, University of Auckland", "kind": "Interview", "title": "Understanding movement through models and collaboration", "intro": "Thor Besier’s work at Auckland connected musculoskeletal biomechanics with computational modeling. In his interview, he reflected on an international research community that included several Whitaker visitors.", "thumbnail": "assets/thor-besier-1.jpg", "date": "2019", "searchText": "Thor Besier Auckland Bioengineering Institute, University of Auckland Biomechanics researcher and Whitaker host Understanding movement through models and collaboration Thor Besier’s work at Auckland connected musculoskeletal biomechanics with computational modeling. In his interview, he reflected on an international research community that included several Whitaker visitors. Interview His research explored human movement and the mechanical demands placed on the body. Models offered a way to connect measurements with questions about the structures and forces involved in movement. Besier remembered the Whitaker program as a valuable route for researchers to join projects abroad. His conversation ranged across disciplines and applications, reflecting an environment where new questions often emerged through exchanges between people with different technical backgrounds."}, {"slug": "prasad-babarenda", "name": "Prasad Babarenda", "institution": "Auckland Bioengineering Institute, University of Auckland", "mapInstitution": "Auckland Bioengineering Institute, University of Auckland", "kind": "Interview", "title": "Modeling how soft tissues change shape", "intro": "Prasad Babarenda’s postdoctoral work at the Auckland Bioengineering Institute focused on the large deformations of soft tissues. Breast biomechanics provided a demanding example of why those changes matter.", "thumbnail": "assets/prasad-babarenda-1.jpg", "date": "2019", "searchText": "Prasad Babarenda Auckland Bioengineering Institute, University of Auckland Postdoctoral fellow Modeling how soft tissues change shape Prasad Babarenda’s postdoctoral work at the Auckland Bioengineering Institute focused on the large deformations of soft tissues. Breast biomechanics provided a demanding example of why those changes matter. Interview When a patient’s position changes between imaging or clinical procedures, the breast changes shape as well. His modeling work addressed how to relate tissue locations across those different configurations, connecting mechanics with a practical imaging challenge. The interview also looked beyond a single project toward academic life. Mentoring and developing research proposals were part of the path he was considering, alongside the technical work of building and understanding computational models."}, {"slug": "geoffrey-handsfield", "name": "Geoffrey Handsfield", "institution": "Auckland Bioengineering Institute, University of Auckland", "mapInstitution": "Auckland Bioengineering Institute, University of Auckland", "kind": "Interview", "title": "Making models useful—and research reproducible", "intro": "Geoffrey Handsfield’s Whitaker postdoctoral experience at Auckland developed into a research-fellow role. His work used computational approaches to understand muscle and other complex biological systems.", "thumbnail": "assets/geoffrey-handsfield-1.jpg", "date": "2019 interview · 2020 alumni reflection", "searchText": "Geoffrey Handsfield Auckland Bioengineering Institute, University of Auckland Research fellow; Whitaker postdoctoral scholar, 2015 Making models useful—and research reproducible Geoffrey Handsfield’s Whitaker postdoctoral experience at Auckland developed into a research-fellow role. His work used computational approaches to understand muscle and other complex biological systems. Interview In his interview, he discussed the promise of human-organ models for clinical research and drug development. He also emphasized a challenge shared by experiments and computation: complex methods can be difficult for other researchers to reproduce. His 2020 alumni reflection connected international experience with personal growth and a broader view of science. He encouraged high standards without perfectionism: research needs to become available for others to use. The value of a model lies partly in whether it can support work beyond the group that created it."}, {"slug": "lauren-ayton", "name": "Lauren Ayton", "institution": "University of Melbourne", "mapInstitution": "University of Melbourne", "kind": "Interview", "title": "Research shaped around people with vision loss", "intro": "Lauren Ayton’s work brought clinical experience and research together around severe vision impairment. At the time of her interview, she held roles spanning the University of Melbourne and the Royal Victorian Eye and Ear Hospital.", "thumbnail": "assets/lauren-ayton-1.jpg", "date": "31 October 2019", "searchText": "Lauren Ayton University of Melbourne Senior research fellow; head of the Vision Optimisation Group Research shaped around people with vision loss Lauren Ayton’s work brought clinical experience and research together around severe vision impairment. At the time of her interview, she held roles spanning the University of Melbourne and the Royal Victorian Eye and Ear Hospital. Interview Her research interests included bionic eyes, gene therapy, assistive technology, and understanding the course of eye disease. Clinical measurements and natural-history studies helped create the foundation needed to design and evaluate research involving patients. The interview highlights the breadth of a translational research team. Developing a technology is only part of the work; understanding people’s needs, collecting meaningful information, and supporting clinical studies are essential parts of investigating whether an idea may be useful."}, {"slug": "fleur-ohare", "name": "Fleur O’Hare", "institution": "Melbourne vision research community", "mapInstitution": "", "kind": "Interview", "title": "The people and planning behind clinical research", "intro": "Fleur O’Hare described clinical research coordination as the framework that allows a study to happen. Her role connected research plans with the participants whose time and experiences make those studies possible.", "thumbnail": "assets/fleur-ohare-1.jpg", "date": "2019", "searchText": "Fleur O’Hare Melbourne vision research community Senior clinical research coordinator The people and planning behind clinical research Fleur O’Hare described clinical research coordination as the framework that allows a study to happen. Her role connected research plans with the participants whose time and experiences make those studies possible. Interview That framework included ethics, protocols, enrollment, and attention to participant safety and wellbeing. With a clinical background, she also contributed to assessments, analysis, and communicating results. Her interests extended into the relationship between vision, movement, and the arts, including work with dancers. The interview reveals how a person’s interests beyond the laboratory can help shape the questions they ask within it."}, {"slug": "james-vince-seth-masters", "name": "James Vince & Seth Masters", "institution": "Walter and Eliza Hall Institute of Medical Research", "mapInstitution": "Walter and Eliza Hall Institute of Medical Research", "kind": "Interview", "title": "Two laboratories, shared questions about inflammation", "intro": "James Vince and Seth Masters described leading small research groups at the Walter and Eliza Hall Institute in Melbourne. Their conversation connected fundamental biological mechanisms with questions arising from inflammatory disease.", "thumbnail": "assets/james-vince-seth-masters-1.jpg", "date": "2019", "searchText": "James Vince & Seth Masters Walter and Eliza Hall Institute of Medical Research Laboratory heads Two laboratories, shared questions about inflammation James Vince and Seth Masters described leading small research groups at the Walter and Eliza Hall Institute in Melbourne. Their conversation connected fundamental biological mechanisms with questions arising from inflammatory disease. Interview Vince’s laboratory investigated cell death and inflammation. Masters’s work included inherited autoinflammatory conditions, using information from patients to explore disease pathways. Their research involved exchanges among basic science, clinical collaborators, and technology specialists. Both reflected on the shift from performing experiments to enabling a group’s research. Funding, communication, and supporting other scientists had become major parts of the day. Their joint interview offers a view of the organizational work behind laboratory discoveries."}, {"slug": "angus-johnston", "name": "Angus Johnston", "institution": "Monash University", "mapInstitution": "Monash University", "kind": "Interview", "title": "Following a material into the cell", "intro": "Angus Johnston’s research brought together physical chemistry, molecular biology, and nanoengineered materials. At Monash, he investigated what happens when engineered materials interact with cells.", "thumbnail": "assets/angus-johnston-1.jpg", "date": "2019", "searchText": "Angus Johnston Monash University Senior lecturer and research fellow Following a material into the cell Angus Johnston’s research brought together physical chemistry, molecular biology, and nanoengineered materials. At Monash, he investigated what happens when engineered materials interact with cells. Interview That work included questions about cellular trafficking and targeted delivery, alongside methods for controlling how proteins are presented on a material. Understanding those interactions required moving between the properties of a designed system and the behavior of a living cell. His teaching and research crossed disciplinary boundaries. The story offers an example of how engineering at very small scales still depends on a broad scientific toolkit—and on asking what a material actually does in its biological setting."}, {"slug": "vijay-rajagopal", "name": "Vijay Rajagopal", "institution": "University of Melbourne", "mapInstitution": "University of Melbourne", "kind": "Interview", "title": "Zooming in from organs to cells", "intro": "Vijay Rajagopal’s research connected the structure of a cell with its mechanical behavior. His route into that work began with multiscale and multiphysics modeling at the Auckland Bioengineering Institute.", "thumbnail": "assets/vijay-rajagopal-1.jpg", "date": "2019", "searchText": "Vijay Rajagopal University of Melbourne Senior lecturer in biomedical engineering Zooming in from organs to cells Vijay Rajagopal’s research connected the structure of a cell with its mechanical behavior. His route into that work began with multiscale and multiphysics modeling at the Auckland Bioengineering Institute. Interview Experience modeling whole organs led to questions at a smaller scale. His Cell Structure and Mechanobiology Group investigated how the organization of cells relates to their function, bringing engineering approaches to biological complexity. He described inspiration from learning about the machinery inside living cells. Moving between scales—from an organ to the structures within a cell—offered new ways to formulate a problem and new connections between computation and biology."}, {"slug": "azade-allahyari", "name": "Azade Allahyari", "institution": "University of Melbourne", "mapInstitution": "University of Melbourne", "kind": "Interview", "title": "A path from medical devices to tissue engineering", "intro": "Azade Allahyari’s international path connected work with biomedical devices in Iran, graduate study in Germany, and a research experience in Melbourne. Each stage offered another way to work at the interface of engineering and medicine.", "thumbnail": "assets/azade-allahyari-1.jpg", "date": "2019", "searchText": "Azade Allahyari University of Melbourne Visiting researcher in tissue engineering A path from medical devices to tissue engineering Azade Allahyari’s international path connected work with biomedical devices in Iran, graduate study in Germany, and a research experience in Melbourne. Each stage offered another way to work at the interface of engineering and medicine. Interview In Melbourne, she described research involving biofabrication, tissue engineering, and decellularization. The experience moved her closer to experimental questions about biological materials after earlier work with medical products. Her interview presents a career shaped through transitions between countries and kinds of work. Rather than following a single fixed route, she used new training and research opportunities to develop her interests. This brief profile retains only the clearly described elements of the transcript."}, {"slug": "korie-grayson", "name": "Korie Grayson", "institution": "University of Michigan", "mapInstitution": "", "kind": "Interview", "title": "From manufacturing questions to research", "intro": "Korie Grayson’s interest in research grew through experience manufacturing medical devices. Seeing a dialysis graft in that setting prompted questions about how products are developed—and how she could contribute to that process.", "thumbnail": "assets/korie-grayson-1.jpg", "date": "22 September 2020", "searchText": "Korie Grayson University of Michigan Postdoctoral researcher in chemical engineering From manufacturing questions to research Korie Grayson’s interest in research grew through experience manufacturing medical devices. Seeing a dialysis graft in that setting prompted questions about how products are developed—and how she could contribute to that process. Interview Her path included chemistry and premedical studies, followed by a biomedical engineering doctorate at Cornell. Courses and research in drug delivery helped connect her interests in biology, materials, and design. At the time of the interview, she was a postdoctoral researcher in chemical engineering at Michigan. Her story shows how work outside an academic laboratory can help clarify a research direction. Questions raised by an existing medical product became a reason to seek the training needed to investigate and develop new ideas."}, {"slug": "ndea-irvin-choy", "name": "N’Dea Irvin-Choy", "institution": "University of Delaware", "mapInstitution": "", "kind": "Interview", "title": "Connecting scientific ambition and public conversation", "intro": "N’Dea Irvin-Choy’s early interest in chemistry and mathematics included the idea of creating a cosmetics line. Biomedical engineering at Rowan offered a route that brought those scientific interests together.", "thumbnail": "", "date": "22 September 2020", "searchText": "N’Dea Irvin-Choy University of Delaware PhD candidate in biomedical engineering Connecting scientific ambition and public conversation N’Dea Irvin-Choy’s early interest in chemistry and mathematics included the idea of creating a cosmetics line. Biomedical engineering at Rowan offered a route that brought those scientific interests together. Interview At Delaware, her doctoral research investigated nanoparticles in the context of pregnancy complications. The project explored targeted delivery as a research question, rather than describing an established treatment. Her interview also connected scientific training with communication beyond the laboratory. Sharing experiences as a biomedical engineer was part of how she helped others understand the field and imagine a place within it. Her path demonstrates how an initial interest can evolve while retaining its underlying curiosity."}, {"slug": "meritxell-meri-martinez", "name": "Meritxell “Meri” Martinez", "institution": "University of Texas at San Antonio", "mapInstitution": "", "kind": "Interview", "title": "Making biomedical engineering easier to discover", "intro": "Meritxell “Meri” Martinez graduated in biomedical engineering from the University of Texas at San Antonio in May 2020. In her interview, she described exploring product development alongside a commitment to explaining the field to others.", "thumbnail": "", "date": "28 August 2020", "searchText": "Meritxell “Meri” Martinez University of Texas at San Antonio Biomedical engineering graduate; product-development engineering intern Making biomedical engineering easier to discover Meritxell “Meri” Martinez graduated in biomedical engineering from the University of Texas at San Antonio in May 2020. In her interview, she described exploring product development alongside a commitment to explaining the field to others. Interview Her internship at Progenerative Medical involved validation testing related to orthopedic devices. It offered a view of how an engineering idea is examined in a product-development setting, alongside questions about business and regulation. She also co-founded BME Life in 2018 to share information, advice, and community around biomedical engineering. Her story joins two kinds of translation: moving technical work toward a product and making an unfamiliar profession understandable to people considering it."}, {"slug": "jeff-hsiao", "name": "Jeff Hsiao", "institution": "ETH Zurich", "mapInstitution": "ETH Zurich", "kind": "Interview", "title": "Working where microfluidics meets molecular design", "intro": "Jeff Hsiao described research in Andrew deMello’s group at ETH Zurich following a Whitaker experience. His work brought together microfluidics and questions about engineered nanoparticles.", "thumbnail": "assets/jeff-hsiao-1.jpg", "date": "23 May 2019", "searchText": "Jeff Hsiao ETH Zurich Research assistant; former Whitaker fellow Working where microfluidics meets molecular design Jeff Hsiao described research in Andrew deMello’s group at ETH Zurich following a Whitaker experience. His work brought together microfluidics and questions about engineered nanoparticles. Interview The interview discussed DNA-coated nanoparticles and their interactions with enzymes, with an interest in possible diagnostic applications. These projects connected the design of small-scale systems with biological behavior that needed to be measured and understood. His experience illustrates an international research path built through laboratory work and new technical questions. Moving between engineering methods and molecular biology offered opportunities to develop skills that did not sit neatly within a single discipline."}, {"slug": "stacy-skaalure", "name": "Stacy Skaalure", "institution": "Imperial College London", "mapInstitution": "Imperial College London", "kind": "Interview", "title": "Materials that respond to their surroundings", "intro": "Stacy Skaalure’s research at Imperial developed from training in chemical and biological engineering. A Whitaker experience was followed by further international research support, allowing her work in the Stevens group to continue.", "thumbnail": "assets/stacy-skaalure-1.jpg", "date": "29 April 2019", "searchText": "Stacy Skaalure Imperial College London Postdoctoral researcher; former Whitaker scholar Materials that respond to their surroundings Stacy Skaalure’s research at Imperial developed from training in chemical and biological engineering. A Whitaker experience was followed by further international research support, allowing her work in the Stevens group to continue. Interview Her interests included hydrogels for tissue engineering, three-dimensional cell cultures, and materials designed to respond to cues such as light or enzymes. These approaches connected the properties of an engineered material with the environment in which it would function. Skaalure described a collaborative setting where learning new methods helped broaden an existing research foundation. Her story shows how an international appointment can become more than a short visit, creating space for a scientific direction to develop over several years."}, {"slug": "gabriella-nilssonhall", "name": "Gabriella Nilssonhall", "institution": "KU Leuven", "mapInstitution": "KU Leuven", "kind": "Interview", "title": "Finding a research direction through exchange", "intro": "Gabriella Nilssonhall’s training took her from Sweden to an Erasmus experience in France and then thesis research in Belgium. That sequence led toward doctoral work in tissue engineering at KU Leuven.", "thumbnail": "assets/gabriella-nilssonhall-1.jpg", "date": "13 May 2019", "searchText": "Gabriella Nilssonhall KU Leuven PhD researcher in tissue engineering Finding a research direction through exchange Gabriella Nilssonhall’s training took her from Sweden to an Erasmus experience in France and then thesis research in Belgium. That sequence led toward doctoral work in tissue engineering at KU Leuven. Interview She described the practical work of cell culture and staining alongside the experience of helping other researchers learn. An interest sparked by school science and later coursework developed into the more open-ended questions of a research project. Her story highlights the way an exchange or thesis placement can help reveal a possible next step. Trying a new research environment provided information about both the science and the daily experience of doing it."}, {"slug": "francois-rannou", "name": "François Rannou", "institution": "Université Paris Descartes / Cochin Hospital", "mapInstitution": "Universite Paris Descartes (now Universite Paris Cite)", "kind": "Interview", "title": "Connecting joint mechanics with clinical questions", "intro": "François Rannou’s career linked clinical care with molecular and cellular research on joint disease. At the time of his interview, he worked within the Paris Descartes and Cochin Hospital community.", "thumbnail": "assets/francois-rannou-1.jpg", "date": "27 May 2019", "searchText": "François Rannou Université Paris Descartes / Cochin Hospital Professor of medicine; rehabilitation and rheumatology clinician Connecting joint mechanics with clinical questions François Rannou’s career linked clinical care with molecular and cellular research on joint disease. At the time of his interview, he worked within the Paris Descartes and Cochin Hospital community. Interview After medical and doctoral training, research experiences at UC Riverside and UCLA introduced approaches that he could connect with cartilage biology. Mechanotransduction—the way cells respond to physical signals—offered a bridge between mechanical questions and disease research. His account illustrates how methods can travel between scientific areas and across countries. Combining clinical experience with basic science helped shape questions about osteoarthritis and other joint conditions, while keeping the research connected to problems encountered in patient care."}, {"slug": "axel-moore", "name": "Axel Moore", "institution": "Imperial College London", "mapInstitution": "Imperial College London", "kind": "Interview", "title": "Expanding the toolkit for cartilage research", "intro": "Axel Moore’s background in mechanical and biomedical engineering led toward questions about cartilage, including how it bears load and provides lubrication. His international research experience helped broaden the methods he could bring to those problems.", "thumbnail": "assets/axel-moore-1.jpg", "date": "1 May 2019", "searchText": "Axel Moore Imperial College London Research associate; former Whitaker scholar Expanding the toolkit for cartilage research Axel Moore’s background in mechanical and biomedical engineering led toward questions about cartilage, including how it bears load and provides lubrication. His international research experience helped broaden the methods he could bring to those problems. Interview At Imperial’s Stevens group, his work connected mechanical questions with biomaterials and cell culture. Learning those approaches meant working across disciplines rather than treating cartilage as only a mechanical system. Moore’s interview described a path shaped by discovering opportunities, pursuing further training, and mentoring students. A new laboratory could provide both a research project and a chance to build capabilities that would change the questions he was able to ask."}, {"slug": "jess-snedeker", "name": "Jess Snedeker", "institution": "ETH Zurich", "mapInstitution": "ETH Zurich", "kind": "Interview", "title": "Creating connections between engineering and orthopedics", "intro": "Jess Snedeker’s role connected engineering research at ETH Zurich with orthopedic medicine at the University of Zurich. Working across those settings placed collaboration at the center of his scientific life.", "thumbnail": "assets/jess-snedeker-1.jpg", "date": "23 May 2019", "searchText": "Jess Snedeker ETH Zurich Associate professor; joint ETH Zurich and University of Zurich appointment Creating connections between engineering and orthopedics Jess Snedeker’s role connected engineering research at ETH Zurich with orthopedic medicine at the University of Zurich. Working across those settings placed collaboration at the center of his scientific life. Interview He described coordinating basic science within an orthopedic research environment. That position involved relating engineering approaches to questions arising in medicine and connecting people whose expertise came from different training traditions. The interview offers a view of interdisciplinary research as an ongoing practice. Building useful connections requires more than bringing disciplines into the same institution: it depends on people learning how to ask questions and work together across their boundaries."}, {"slug": "daniel-freer", "name": "Daniel Freer", "institution": "Imperial College London", "mapInstitution": "Imperial College London", "kind": "Interview", "title": "Engineering assistance around human signals", "intro": "Daniel Freer’s Whitaker experience supported a master’s program in medical robotics and image-guided intervention at Imperial. It became part of a longer path into doctoral research.", "thumbnail": "assets/daniel-freer-1.jpg", "date": "29 April 2019", "searchText": "Daniel Freer Imperial College London PhD researcher, Hamlyn Centre; former Whitaker fellow Engineering assistance around human signals Daniel Freer’s Whitaker experience supported a master’s program in medical robotics and image-guided intervention at Imperial. It became part of a longer path into doctoral research. Interview His projects included wearable assistance for tremor and work with EEG-based brain–computer interfaces. Shared-control approaches raised questions about how a person and a robotic system could contribute together to a task. Freer’s story connects an international training opportunity with the freedom to explore different applications. The projects shared an interest in human signals and robotic assistance, while opening possibilities beyond any one device or clinical setting."}, {"slug": "jaap-van-dieen", "name": "Jaap van Dieën", "institution": "Vrije Universiteit Amsterdam (VU)", "mapInstitution": "Vrije Universiteit Amsterdam (VU)", "kind": "Interview", "title": "Asking how people keep their balance", "intro": "Jaap van Dieën’s biomechanics research investigated everyday actions that become complex when examined closely: maintaining posture, walking, and keeping balance. His work connected those questions with aging, neurological conditions, and low-back pain.", "thumbnail": "assets/jaap-van-dieen-1.jpg", "date": "3 May 2019", "searchText": "Jaap van Dieën Vrije Universiteit Amsterdam (VU) Professor of biomechanics Asking how people keep their balance Jaap van Dieën’s biomechanics research investigated everyday actions that become complex when examined closely: maintaining posture, walking, and keeping balance. His work connected those questions with aging, neurological conditions, and low-back pain. Interview At VU Amsterdam, he described research on trunk control and walking, including collaborations involving predictive foot placement and exoskeletons. Understanding movement required looking at both mechanical demands and the ways people respond to them. His interview also reflected enjoyment of the variety in academic work, from teaching to developing research with students. The connection between movement in daily life and movement as a scientific problem gave the work a broad, human context."}, {"slug": "anna-blakney-robin-shattock", "name": "Anna Blakney & Robin Shattock", "institution": "Imperial College London", "mapInstitution": "Imperial College London", "kind": "Interview", "title": "Building vaccines across disciplinary boundaries", "intro": "Anna Blakney and Robin Shattock discussed vaccine research at Imperial in April 2019. Their conversation brought engineering approaches to delivery together with biological questions about immune responses.", "thumbnail": "assets/anna-blakney-robin-shattock-1.jpg", "date": "29 April 2019", "searchText": "Anna Blakney & Robin Shattock Imperial College London Postdoctoral researcher and vaccine research leader Building vaccines across disciplinary boundaries Anna Blakney and Robin Shattock discussed vaccine research at Imperial in April 2019. Their conversation brought engineering approaches to delivery together with biological questions about immune responses. Interview Blakney’s path included Whitaker-supported postdoctoral research and work on lipid nanoparticles for RNA vaccine delivery, including HIV-related research. Shattock described the challenges of translating vaccine and antiviral ideas into approaches that could be manufactured and made accessible. The joint interview emphasized complementary expertise and room for creative thinking. This conversation predates the COVID-19 pandemic; it records the research questions and ambitions of that time, without attributing later developments to the interview."}, {"slug": "marloes-groot", "name": "Marloes Groot", "institution": "Vrije Universiteit Amsterdam (VU)", "mapInstitution": "Vrije Universiteit Amsterdam (VU)", "kind": "Interview", "title": "Taking an imaging idea toward the hospital", "intro": "Marloes Groot’s research used light to investigate biological tissue. Her path from photosynthesis and laser research toward medical imaging developed through collaborations with people asking clinical questions.", "thumbnail": "assets/marloes-groot-1.jpg", "date": "6 May 2019", "searchText": "Marloes Groot Vrije Universiteit Amsterdam (VU) Professor of biophotonics and medical imaging Taking an imaging idea toward the hospital Marloes Groot’s research used light to investigate biological tissue. Her path from photosynthesis and laser research toward medical imaging developed through collaborations with people asking clinical questions. Interview At VU Amsterdam, her group worked with higher-harmonic microscopy, including efforts to move from a laboratory system toward equipment that could be used in a hospital. Brain and lung collaborations helped connect technical development with different tissue-imaging needs. Groot emphasized the value of good supervision and projects that are feasible to carry out. Her account shows how a technology gains direction through the people who may use it, as well as through advances in the instrument itself."}, {"slug": "andreas-hierlemann", "name": "Andreas Hierlemann", "institution": "ETH Zurich", "mapInstitution": "ETH Zurich", "kind": "Interview", "title": "Tools for listening to cells", "intro": "Andreas Hierlemann’s laboratory at ETH Zurich’s Basel-based department connected microtechnology with biological systems. His own training in physical chemistry developed into work on sensors and tools for cell research.", "thumbnail": "assets/andreas-hierlemann-1.jpg", "date": "23 May 2019", "searchText": "Andreas Hierlemann ETH Zurich Professor of biosystems engineering, Basel Tools for listening to cells Andreas Hierlemann’s laboratory at ETH Zurich’s Basel-based department connected microtechnology with biological systems. His own training in physical chemistry developed into work on sensors and tools for cell research. Interview The group’s interests included high-density microelectrode arrays for recording signals from neurons and cardiac cells, alongside microfluidic and microtissue systems. These tools offered ways to study living systems through carefully designed experimental platforms. Hierlemann’s interview described a career that changed through opportunities and developing interests. Rather than assuming a single guaranteed route, he emphasized adapting as new questions and possibilities emerge. Technical depth and openness to change could develop together."}, {"slug": "itamar-ronen", "name": "Itamar Ronen", "institution": "Leiden University Medical Center", "mapInstitution": "", "kind": "Interview", "title": "From chemistry to questions about living tissue", "intro": "Itamar Ronen’s path into medical imaging began in chemistry and developed through research in Minnesota, Boston, and the Netherlands. At Leiden University Medical Center, he worked on MRI methods for understanding tissue.", "thumbnail": "assets/itamar-ronen-1.jpg", "date": "7 May 2019", "searchText": "Itamar Ronen Leiden University Medical Center Associate professor of radiology; MRI researcher From chemistry to questions about living tissue Itamar Ronen’s path into medical imaging began in chemistry and developed through research in Minnesota, Boston, and the Netherlands. At Leiden University Medical Center, he worked on MRI methods for understanding tissue. Interview His interests included spectroscopy and diffusion measurements that investigate tissue microstructure. The work connected physical and chemical principles with questions about biological organization and disease. Ronen’s interview reflected the influence of working in different research and clinical environments. Encounters with patient-oriented work helped shape the questions he wanted to pursue, while a foundation in the physical sciences supplied tools for investigating them."}, {"slug": "frank-luyten", "name": "Frank Luyten", "institution": "KU Leuven", "mapInstitution": "KU Leuven", "kind": "Interview", "title": "Keeping basic science close to patient needs", "intro": "Frank Luyten’s career combined clinical rheumatology with a foundation in biochemistry and research. After training in Ghent, he spent eleven years at the U.S. National Institutes of Health before returning to Belgium.", "thumbnail": "assets/frank-luyten-1.jpg", "date": "13 May 2019", "searchText": "Frank Luyten KU Leuven Professor and rheumatology clinician Keeping basic science close to patient needs Frank Luyten’s career combined clinical rheumatology with a foundation in biochemistry and research. After training in Ghent, he spent eleven years at the U.S. National Institutes of Health before returning to Belgium. Interview At KU Leuven, his interests included regenerative medicine and cartilage repair. The work connected basic biological questions with the challenges encountered in caring for people with joint disease. His interview presented international experience as part of a long research trajectory. Moving between institutions and between clinical and laboratory work offered different ways to understand a problem, while patient needs remained a reason to pursue the underlying science."}, {"slug": "ton-van-der-steen", "name": "Ton van der Steen", "institution": "Erasmus MC (Erasmus University Medical Center)", "mapInstitution": "Erasmus MC (Erasmus University Medical Center)", "kind": "Interview", "title": "Following sound into cardiovascular research", "intro": "Ton van der Steen’s interest in sound and applied physics developed into a career in biomedical engineering. His path connected training in Delft and Nijmegen with cardiovascular research in Rotterdam.", "thumbnail": "assets/ton-van-der-steen-1.jpg", "date": "9 May 2019", "searchText": "Ton van der Steen Erasmus MC (Erasmus University Medical Center) Head of biomedical engineering Following sound into cardiovascular research Ton van der Steen’s interest in sound and applied physics developed into a career in biomedical engineering. His path connected training in Delft and Nijmegen with cardiovascular research in Rotterdam. Interview At Erasmus MC, his group investigated ultrasound and optical approaches relevant to diagnosis and therapy. Engineering methods were developed in conversation with medical questions, requiring collaboration across technical and clinical expertise. His interview linked scientific direction with personal interests and the influence of research environments. A fascination with how sound works became part of a larger effort to create useful ways of examining and interacting with the cardiovascular system."}, {"slug": "oleg-prymak", "name": "Oleg Prymak", "institution": "University of Duisburg-Essen", "mapInstitution": "University of Duisburg-Essen", "kind": "Interview", "title": "Using materials science to ask biological questions", "intro": "Oleg Prymak’s international path began in solid-state physics in Ukraine and continued through doctoral research in Germany. Biomaterials became a connection between that physical-science background and biomedical engineering.", "thumbnail": "assets/oleg-prymak-1.jpg", "date": "16 May 2019", "searchText": "Oleg Prymak University of Duisburg-Essen X-ray diffraction research leader Using materials science to ask biological questions Oleg Prymak’s international path began in solid-state physics in Ukraine and continued through doctoral research in Germany. Biomaterials became a connection between that physical-science background and biomedical engineering. Interview At Duisburg-Essen, he led work in X-ray diffraction and participated in projects involving materials such as bone-related ceramics and nanoparticles. Understanding material structure provided a foundation for investigating their properties and possible uses. His story reflects the importance of methods that serve many kinds of research. Expertise in characterizing a material can become a bridge between laboratories, countries, and applications, allowing a physicist’s questions to contribute to biological and medical projects."}, {"slug": "brittany-brumback", "name": "Brittany Brumback", "institution": "University of Melbourne", "mapInstitution": "University of Melbourne", "kind": "Interview", "title": "Making an international semester possible", "intro": "Brittany Brumback used a Whitaker undergraduate grant to study for a semester at the University of Melbourne. By the time of her interview, she was a doctoral candidate at Washington University in St. Louis.", "thumbnail": "", "date": "18 October 2019", "searchText": "Brittany Brumback University of Melbourne Doctoral candidate, Washington University in St. Louis; Whitaker alumna Making an international semester possible Brittany Brumback used a Whitaker undergraduate grant to study for a semester at the University of Melbourne. By the time of her interview, she was a doctoral candidate at Washington University in St. Louis. Interview The grant supported an educational experience tied to her biomedical engineering degree. Arranging it required navigating course approvals and learning how a different university organized its teaching. Some of those practical details became clearer only through conversations with people who knew the system. She encouraged students to seek advice from study-abroad staff, previous participants, and people at the host institution. Her experience also helped make the route easier for later students. A worthwhile opportunity might require persistence and preparation before it becomes an established path."}, {"slug": "natalia-trayanova", "name": "Natalia Trayanova", "institution": "Johns Hopkins University", "mapInstitution": "", "kind": "Interview", "title": "Building a scientific path without a ready-made route", "intro": "Natalia Trayanova’s interview explored the personal circumstances behind an international scientific career. Her move from Bulgaria to the United States took place under constraints very different from a planned student exchange.", "thumbnail": "", "date": "17 July 2019", "searchText": "Natalia Trayanova Johns Hopkins University Researcher and academic mentor Building a scientific path without a ready-made route Natalia Trayanova’s interview explored the personal circumstances behind an international scientific career. Her move from Bulgaria to the United States took place under constraints very different from a planned student exchange. Interview She described a strong early interest in physics and the challenge of finding her own way in a new academic environment. The account resisted a simple story in which each career step followed from a freely chosen, carefully arranged plan. Looking at academic life from the perspective of a research leader, she also described the tension between organizational responsibilities and time for science. Her story adds another dimension to the archive: international careers can be shaped by historical circumstances, persistence, and opportunities that were difficult to anticipate."}, {"slug": "joseph-yu", "name": "Joseph Yu", "institution": "Imperial College London", "mapInstitution": "Imperial College London", "kind": "Alumni reflection", "title": "Learning which questions to ask", "intro": "Joseph Yu received a Whitaker grant in 2013 and shared this reflection with EverydayBME in 2020. The experience was hosted by Imperial College London.", "thumbnail": "assets/joseph-yu-1.jpg", "date": "2020 alumni reflection", "searchText": "Joseph Yu Imperial College London PhD student, Johns Hopkins University Learning which questions to ask Joseph Yu received a Whitaker grant in 2013 and shared this reflection with EverydayBME in 2020. The experience was hosted by Imperial College London. Alumni reflection Joseph Yu’s Whitaker experience at Imperial helped develop more than technical expertise. In his alumni reflection, he connected international education with empathy and a more nuanced approach to communication. Identifying a worthwhile research question was a central challenge for him. The experience of working across cultural expectations also made clear that effective collaboration depends on listening and learning how other people communicate."}, {"slug": "alexis-krueger", "name": "Alexis Krueger", "institution": "University of Genoa", "mapInstitution": "University of Genoa", "kind": "Alumni reflection", "title": "Discovering the pleasure of teaching", "intro": "Alexis Krueger received a Whitaker grant in 2016 and shared this reflection with EverydayBME in 2020. The experience was hosted by University of Genoa.", "thumbnail": "", "date": "2020 alumni reflection", "searchText": "Alexis Krueger University of Genoa Systems Test Engineer, Exact Sciences Discovering the pleasure of teaching Alexis Krueger received a Whitaker grant in 2016 and shared this reflection with EverydayBME in 2020. The experience was hosted by University of Genoa. Alumni reflection Alexis Krueger’s experience in Maura Casadio’s laboratory at Genoa included mentoring undergraduate students. That responsibility helped reveal an interest in teaching alongside her engineering work. Writing in 2020 from a systems-test-engineering role at Exact Sciences, she reflected on a definition of success that included fulfillment and family. Her story leaves room for career directions to change as experience clarifies what matters."}, {"slug": "amanda-chen", "name": "Amanda Chen", "institution": "University of Cambridge", "mapInstitution": "University of Cambridge", "kind": "Alumni reflection", "title": "Growing through a year of new connections", "intro": "Amanda Chen received a Whitaker grant in 2014 and shared this reflection with EverydayBME in 2020. The experience was hosted by University of Cambridge.", "thumbnail": "assets/amanda-chen-1.jpg", "date": "2020 alumni reflection", "searchText": "Amanda Chen University of Cambridge PhD Candidate, MIT Biological Engineering Growing through a year of new connections Amanda Chen received a Whitaker grant in 2014 and shared this reflection with EverydayBME in 2020. The experience was hosted by University of Cambridge. Alumni reflection Amanda Chen spent a Whitaker-supported year at Cambridge in Nigel Slater’s bioscience engineering group. Her reflection connected laboratory learning with the wider community she found through college life. Serving as an academic chair in Churchill’s graduate community brought her into contact with people across disciplines and cultures. She also reflected on mentors who encouraged creative experiments and thoughtful risk-taking, lessons she carried into doctoral training at MIT."}, {"slug": "sydney-geissler", "name": "Sydney Geissler", "institution": "ETH Zurich", "mapInstitution": "ETH Zurich", "kind": "Alumni reflection", "title": "A wider view of science—and of a career", "intro": "Sydney Geissler received a Whitaker grant in 2015 and shared this reflection with EverydayBME in 2020. The experience was hosted by ETH Zurich.", "thumbnail": "assets/sydney-geissler-1.jpg", "date": "2020 alumni reflection", "searchText": "Sydney Geissler ETH Zurich Medical Writer, Medtronic A wider view of science—and of a career Sydney Geissler received a Whitaker grant in 2015 and shared this reflection with EverydayBME in 2020. The experience was hosted by ETH Zurich. Alumni reflection Sydney Geissler’s Whitaker experience brought her to Andreas Hierlemann’s group at ETH Zurich in Basel. The exchange offered a broader perspective on scientific work and the people who make it possible. In her 2020 reflection, she emphasized mentoring as a reciprocal relationship in which both people learn. Writing from a medical-writing role at Medtronic, she also allowed space for uncertainty: a career can develop without every later step being known at the beginning."}, {"slug": "martin-spang", "name": "Martin Spang", "institution": "Cardiff University", "mapInstitution": "Cardiff University", "kind": "Alumni reflection", "title": "Confidence built through an international year", "intro": "Martin Spang received a Whitaker grant in 2015 and shared this reflection with EverydayBME in 2020. The experience was hosted by Cardiff University.", "thumbnail": "assets/martin-spang-1.jpg", "date": "2020 alumni reflection", "searchText": "Martin Spang Cardiff University PhD student, UC San Diego Confidence built through an international year Martin Spang received a Whitaker grant in 2015 and shared this reflection with EverydayBME in 2020. The experience was hosted by Cardiff University. Alumni reflection Martin Spang’s Whitaker experience at Cardiff helped him grow more confident in an unfamiliar environment. Friendships formed around the laboratory became a lasting part of that experience. By his 2020 reflection, he was a doctoral researcher at UC San Diego investigating injectable hydrogels for heart-repair research. His account connected scientific development with the confidence and relationships that come from learning to work abroad."}, {"slug": "ryan-geiser", "name": "Ryan Geiser", "institution": "University of Cambridge", "mapInstitution": "University of Cambridge", "kind": "Alumni reflection", "title": "Finding a scientific home through mentorship", "intro": "Ryan Geiser received a Whitaker grant in 2017 and shared this reflection with EverydayBME in 2020. The experience was hosted by University of Cambridge.", "thumbnail": "assets/ryan-geiser-1.jpg", "date": "2020 alumni reflection", "searchText": "Ryan Geiser University of Cambridge PhD Candidate, University of Cambridge Finding a scientific home through mentorship Ryan Geiser received a Whitaker grant in 2017 and shared this reflection with EverydayBME in 2020. The experience was hosted by University of Cambridge. Alumni reflection Ryan Geiser’s Whitaker experience at Cambridge became part of a doctoral path at the Centre for Misfolding Diseases. He remembered Chris Dobson not only for scientific guidance but also for generosity, encouragement, and personal support. His reflection described a research community extending beyond the laboratory, through college life, rowing, travel, and friendships across cultures. Those relationships helped make an unfamiliar place feel like home and became part of his growth as a scientist."}, {"slug": "taylor-moehling", "name": "Taylor Moehling", "institution": "Emerging Pathogens Institute (Haiti field site)", "mapInstitution": "Emerging Pathogens Institute (Haiti field site)", "kind": "Alumni reflection", "title": "Designing with the people who will use a test", "intro": "Taylor Moehling received a Whitaker grant in 2016 and shared this reflection with EverydayBME in 2020. The experience was hosted by Emerging Pathogens Institute (Haiti field site).", "thumbnail": "assets/taylor-moehling-1.jpg", "date": "2020 alumni reflection", "searchText": "Taylor Moehling Emerging Pathogens Institute (Haiti field site) Graduate Research Assistant, Purdue University Designing with the people who will use a test Taylor Moehling received a Whitaker grant in 2016 and shared this reflection with EverydayBME in 2020. The experience was hosted by Emerging Pathogens Institute (Haiti field site). Alumni reflection Taylor Moehling’s Whitaker experience in Haiti helped ground a biomedical engineering project in its intended setting. She was developing a low-cost paper-based test to detect Vibrio cholerae in environmental water. Conversations with field workers, laboratory technicians, doctors, and community health workers informed the project’s direction and questions about usability. Writing in 2020, she had also completed a public-health master’s degree, bringing that perspective together with her engineering training."}, {"slug": "david-bradway", "name": "David Bradway", "institution": "Technical University of Denmark (DTU)", "mapInstitution": "Technical University of Denmark (DTU)", "kind": "Alumni reflection", "title": "Becoming a scientist through collaboration", "intro": "David Bradway received a Whitaker grant in 2013 and shared this reflection with EverydayBME in 2020. The experience was hosted by Technical University of Denmark (DTU).", "thumbnail": "assets/david-bradway-1.jpg", "date": "2020 alumni reflection", "searchText": "David Bradway Technical University of Denmark (DTU) Research Scientist, Duke University Becoming a scientist through collaboration David Bradway received a Whitaker grant in 2013 and shared this reflection with EverydayBME in 2020. The experience was hosted by Technical University of Denmark (DTU). Alumni reflection David Bradway spent fifteen months at the Technical University of Denmark during his Whitaker postdoctoral experience. Working with Jørgen Arendt Jensen continued a collaboration between his host and home research groups. His work included real-time processing of Doppler ultrasound data and visualization of blood-flow measurements. In his 2020 reflection from Duke, he described an ongoing shift from engineering practice toward scientific research, alongside increasing project-management and laboratory responsibilities."}, {"slug": "julie-kohn", "name": "Julie Kohn", "institution": "University of Cape Town (UCT)", "mapInstitution": "University of Cape Town (UCT)", "kind": "Alumni reflection", "title": "An international experience that led toward teaching", "intro": "Julie Kohn received a Whitaker grant in 2016 and shared this reflection with EverydayBME in 2020. The experience was hosted by University of Cape Town (UCT).", "thumbnail": "assets/julie-kohn-1.jpg", "date": "2020 alumni reflection", "searchText": "Julie Kohn University of Cape Town (UCT) Assistant Professor of Biomedical Engineering, University of Delaware An international experience that led toward teaching Julie Kohn received a Whitaker grant in 2016 and shared this reflection with EverydayBME in 2020. The experience was hosted by University of Cape Town (UCT). Alumni reflection Julie Kohn’s Whitaker experience in Cape Town included research with Thomas Franz and volunteer tutoring through the Amy Foundation. Both experiences helped shape her interest in education and global biomedical engineering. A later Fulbright experience in Tanzania continued that direction. Writing in 2020 from an assistant-professor role at the University of Delaware, she reflected on a path in which teaching and international engagement had become closely connected."}, {"slug": "jan-mangual", "name": "Jan Mangual", "institution": "University of Florence", "mapInstitution": "", "kind": "Alumni reflection", "title": "When an exchange changes the long-term plan", "intro": "Jan Mangual received a Whitaker grant in 2011 and shared this reflection with EverydayBME in 2020. The experience was hosted by University of Florence.", "thumbnail": "", "date": "2020 alumni reflection", "searchText": "Jan Mangual University of Florence Scientist, Abbott When an exchange changes the long-term plan Jan Mangual received a Whitaker grant in 2011 and shared this reflection with EverydayBME in 2020. The experience was hosted by University of Florence. Alumni reflection Jan Mangual’s Whitaker postdoctoral experience in Florence became a turning point in his international career. He reflected on the influence of mentors and the relationships built through research in Italy. Writing in 2020 from a scientist role at Abbott, he connected that experience with subsequent work in European cardiovascular-device research and development. His story illustrates how an exchange intended as one stage of training can shape much longer-term professional choices."}, {"slug": "hattie-cutcliffe", "name": "Hattie Cutcliffe", "institution": "Chalmers University of Technology", "mapInstitution": "Chalmers University of Technology", "kind": "Alumni reflection", "title": "Learning to navigate scientific uncertainty", "intro": "Hattie Cutcliffe received a Whitaker grant in 2013 and shared this reflection with EverydayBME in 2020. The experience was hosted by Chalmers University of Technology.", "thumbnail": "assets/hattie-cutcliffe-1.jpg", "date": "2020 alumni reflection", "searchText": "Hattie Cutcliffe Chalmers University of Technology Postdoctoral Associate, Duke University Learning to navigate scientific uncertainty Hattie Cutcliffe received a Whitaker grant in 2013 and shared this reflection with EverydayBME in 2020. The experience was hosted by Chalmers University of Technology. Alumni reflection Hattie Cutcliffe’s Whitaker experience took her to the SAFER research environment at Chalmers, working with Karin Brolin. Her reflection also recognized the influence of her home mentor, Lou DeFrate. Writing as a Duke postdoctoral researcher in 2020, she discussed learning to work with uncertainty and to advocate for herself as a scientist. The experience abroad formed part of that growth, alongside the technical questions that shaped her research."}, {"slug": "erika-pliner", "name": "Erika Pliner", "institution": "Neuroscience Research Australia (NeuRA)", "mapInstitution": "Neuroscience Research Australia (NeuRA)", "kind": "Alumni reflection", "title": "Bringing human movement into fall-risk research", "intro": "Erika Pliner received a Whitaker grant in 2017 and shared this reflection with EverydayBME in 2020. The experience was hosted by Neuroscience Research Australia (NeuRA).", "thumbnail": "assets/erika-pliner-1.jpg", "date": "2020 alumni reflection", "searchText": "Erika Pliner Neuroscience Research Australia (NeuRA) Postdoctoral fellow, Neuroscience Research Australia Bringing human movement into fall-risk research Erika Pliner received a Whitaker grant in 2017 and shared this reflection with EverydayBME in 2020. The experience was hosted by Neuroscience Research Australia (NeuRA). Alumni reflection Erika Pliner’s Whitaker experience at NeuRA developed into further research there. Her work connected human movement and earlier occupational research with questions about ladder use and falls among older adults. In her 2020 reflection, she described the interaction of physical, cognitive, and psychological factors. The international experience offered a setting in which biomechanics could meet a wider view of human behavior and the practical situations in which injuries occur."}];
